// Central failure summary: sanitized, never credentials or raw headers.
const item = $input.all()[0].json;
const execution = item.execution || {};
const failed = item.workflow || {};
const message = String((execution.error && execution.error.message) || 'unknown error').slice(0, 500);
let category = 'unknown';
if (/401|403|invalid signature|api key|422|validation/i.test(message)) {
  category = 'permanent_auth_or_validation';
} else if (/ECONNREFUSED|ECONNRESET|ETIMEDOUT|EAI_AGAIN|timeout|5\d\d|socket/i.test(message)) {
  category = 'temporary_crm_or_network';
}
return [{
  json: {
    failed_workflow: failed.name || 'unknown',
    execution_id: execution.id || null,
    last_node: execution.lastNodeExecuted || 'unknown',
    category,
    message,
    observed_at: new Date().toISOString(),
  },
}];
